 if 'table' in d:
  d['table']['headers']=d['table'].get('headers',d['table'].get('columns'));d['table']['rows']=[[str(x) for x in r] for r in d['table']['rows']]
 if 'score_strip' in d:d['footer']+=((' · ' if d['footer'] else '')+'Selected-turn scores: '+', '.join(f'{a} {b}' for a,b in d['score_strip']))
 if 'metrics' in d:d['footer']=' · '.join(x['label']+': '+x['value'] for x in d['metrics'])
 if d.get('full_prompt'):d['notes']+='\n\nFULL SHARED JUDGE TEMPLATE (verbatim):\n'+Path(d['full_prompt']).read_text()
 d['notes']+='\n\n'+json.dumps({'sources':d.get('sources',d.get('provenance',[])),'case':d.get('case_label'),'judge_details_file':'outputs/arena/selected_cases.json'},ensure_ascii=False,indent=2)
 return d
